#fps display
clock = pygame.time.Clock()
def displayFPS(screen, fontSize):
    font = pygame.font.SysFont(None, fontSize)
    fps = int(clock.get_fps())
    fps_text = font.render(f"FPS: {fps}", True, (0, 0, 0))
    screen.blit(fps_text, (10, 10))

