class Player():
    def __init__(self, pos):
        self.pos = pos

        self.vel = (0, 0)
        self.gravity = (0, 0.5)
        self.gunForce = 15

        self.shotsLeft = 10
        self.score = 0

        #sprite stuff
        self.angle = 0
        self.shadowYoffset = 15
        self.originalImage = pygame.image.load("Assets/shotgun_white.png").convert_alpha()
        self.originalImage = pygame.transform.scale(self.originalImage, (150, 150 * 0.2616))
        self.image = self.originalImage
        self.rect = self.image.get_rect(center=(self.pos[0], self.pos[1]))

        #shadowstuff
        self.originalImage_shdw = pygame.image.load("Assets/shotgun_shadow.png").convert_alpha()
        self.originalImage_shdw = pygame.transform.scale(self.originalImage_shdw, (150, 150 * 0.2616))
        self.image_shdw = self.originalImage_shdw
        self.rect_shdw = self.image_shdw.get_rect(center=(self.pos[0], self.pos[1] + self.shadowYoffset))

    def draw(self):
        #get angle to moue
        x1, y1 = self.pos
        x2, y2 = pygame.mouse.get_pos()

        dx = x2 - x1
        dy = y2 - y1

        angle_rad = math.atan2(dy, dx)
        angle_deg = math.degrees(angle_rad)
        self.angle = angle_deg

        self.image = pygame.transform.rotate(self.originalImage, -self.angle)
        self.rect = self.image.get_rect()
        self.rect.centerx = self.pos[0]
        self.rect.centery = self.pos[1]

        self.image_shdw = pygame.transform.rotate(self.originalImage_shdw, -self.angle)
        self.rect_shdw = self.image_shdw.get_rect()
        self.rect_shdw.centerx = self.pos[0]
        self.rect_shdw.centery = self.pos[1] + self.shadowYoffset

        #blit order
        screen.blit(self.image_shdw, self.rect_shdw)
        screen.blit(self.image, self.rect)

    def physicsUpdate(self):

        #apply gravity accelaration
        self.vel = (self.vel[0], self.vel[1] + self.gravity[1])

        #apply velocity
        self.pos = (self.pos[0] + self.vel[0], self.pos[1] + self.vel[1])

        #bounce of edges
        if self.pos[0] < 0:
            self.pos = (0, self.pos[1])
            self.vel = (self.vel[0] * -1, self.vel[1])
        if self.pos[0] > screenWidth:
            self.pos = (screenWidth, self.pos[1])
            self.vel = (self.vel[0] * -1, self.vel[1])

    def shoot(self):
        #do knockback

        #get to mouse direction
        mPos = pygame.mouse.get_pos()
        vecToMouse = (mPos[0] - self.pos[0], mPos[1] - self.pos[1])
        oppositeVec = (vecToMouse[0] * -1, vecToMouse[1] * -1)
        mag = math.sqrt(oppositeVec[0] ** 2 + oppositeVec[1] ** 2)
        normalizedVec = (oppositeVec[0] / mag, oppositeVec[1] / mag)

        #apply opposite force by gunForce
        self.vel = (normalizedVec[0] * self.gunForce, normalizedVec[1] * self.gunForce)

        #check clay shots using line intersections
        #do 6 spread lines from gun and check intersections with clays
        shotAngles = []
        spreadAngle = 30
        for i in range(24):
            shotAngle = -spreadAngle/2 + i * (spreadAngle/24)
            shotAngles.append(shotAngle)

        numOfClaysShot = 0
        for i in range(len(shotAngles)):
            shotAngle = self.angle + shotAngles[i]

            #get shot points
            s1 = self.pos
            angle_rad = math.radians(shotAngle)
            s2 = (s1[0] + math.cos(angle_rad) * 1200, s1[1] + math.sin(angle_rad) * 1200)

            #pygame.draw.line(screen, (255, 0, 0), s1, s2, 4)

            for j in range(len(clays)):
                #get 2 lines crossing the clay to get a "hitbox"
                clay = clays[j]
                p1 = (clay.pos[0] - 30, clay.pos[1])
                p2 = (clay.pos[0] + 30, clay.pos[1])
                p3 = (clay.pos[0], clay.pos[1] - 30)
                p4 = (clay.pos[0], clay.pos[1] + 30)

                #check if lines intersect
                doesIntersect = False
                in1 = linenItersection(s1, s2, p1, p2, True)
                in2 = linenItersection(s1, s2, p3, p4, True)
                if in1 != None and in2 != None:
                    doesIntersect = True

                if doesIntersect and clay.hasBeenShot == False:
                    numOfClaysShot += 1
                    clay.hasBeenShot = True
                    clay.isDead = True

        self.shotsLeft += 2 * numOfClaysShot
        self.score += numOfClaysShot

class Clay():
    def __init__(self, pos):
        clays.append(self)
        self.pos = pos

        self.vel = (0, 0)
        self.gravity = (0, 0.5)

        self. angle = 0
        self.angleVel = 0

        self.isDead = False
        self.hasBeenShot = False

        #sprite stuff
        self.angle = 0
        self.shadowYoffset = 15
        self.originalImage = pygame.image.load("Assets/target_white.png").convert_alpha()
        self.originalImage = pygame.transform.scale(self.originalImage, (60, 60))
        self.image = self.originalImage
        self.rect = self.image.get_rect(center=(self.pos[0], self.pos[1]))

        #shadowstuff
        self.originalImage_shdw = pygame.image.load("Assets/target_shadow.png").convert_alpha()
        self.originalImage_shdw = pygame.transform.scale(self.originalImage_shdw, (60, 60))
        self.image_shdw = self.originalImage_shdw
        self.rect_shdw = self.image_shdw.get_rect(center=(self.pos[0], self.pos[1] + self.shadowYoffset))

    def draw(self):
        self.angle += self.angleVel

        self.image = pygame.transform.rotate(self.originalImage, -self.angle)
        self.rect = self.image.get_rect()
        self.rect.centerx = self.pos[0]
        self.rect.centery = self.pos[1]

        self.image_shdw = pygame.transform.rotate(self.originalImage_shdw, -self.angle)
        self.rect_shdw = self.image_shdw.get_rect()
        self.rect_shdw.centerx = self.pos[0]
        self.rect_shdw.centery = self.pos[1] + self.shadowYoffset

        #blit order
        screen.blit(self.image_shdw, self.rect_shdw)
        screen.blit(self.image, self.rect)

    def physicsUpdate(self):

        #apply gravity accelaration
        self.vel = (self.vel[0], self.vel[1] + self.gravity[1])

        #apply velocity
        self.pos = (self.pos[0] + self.vel[0], self.pos[1] + self.vel[1])

