def spawnClay():
    rand = random.randint(0, 1)
    pos = [(-50, 700 - random.randint(0, 80)), (screenWidth + 50, 700 - random.randint(0, 80))][rand]
    vel = [(12, -10), (-12, -10)][rand]
    angleVel = random.uniform(-90, 90)

    newClay = Clay(pos)
    newClay.vel = vel
    newClay.angleVel = 0

# - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

plyr = Player((400, 200))

clays = []
clayReqCooldown = 0 * 60
clayCurrCooldown = 0

font = pygame.font.SysFont(None, 90)
fps = int(clock.get_fps())

running = True
while running:

    screen.fill((0, 0, 0))
    drawBackground()

    #events
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False

        elif event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 1:
                if plyr.shotsLeft > 0:
                    plyr.shoot()
                    plyr.shotsLeft -= 1

    #text shadows
    shotsleft_text = font.render(f"{plyr.shotsLeft}", True, (200, 200, 200))
    screen.blit(shotsleft_text, (1/4 * screenWidth - 30, screenHeight/2 - 55))

    score_text = font.render(f"{plyr.score}", True, (200, 200, 200))
    screen.blit(score_text, (3/4 * screenWidth - 15, screenHeight/2 - 55))

    #text front
    shotsleft_text = font.render(f"{plyr.shotsLeft}", True, (255, 255, 255))
    screen.blit(shotsleft_text, (1/4 * screenWidth - 30, screenHeight/2 - 60))

    score_text = font.render(f"{plyr.score}", True, (255, 255, 255))
    screen.blit(score_text, (3/4 * screenWidth - 15, screenHeight/2 - 60))

    #spawn clays
    clayCurrCooldown += 1
    if clayCurrCooldown > clayReqCooldown:
        clayCurrCooldown = 0
        clayReqCooldown = random.uniform(0.7, 1.5) * 60
        spawnClay()

    #update player
    plyr.physicsUpdate()
    plyr.draw()

    #update clays
    for i in range(len(clays)):
        clays[i].physicsUpdate()
        clays[i].draw()

    #remove dead clays
    clays = [clay for clay in clays if not clay.isDead and clay.pos[1] < screenHeight]

    #check for death
    if plyr.pos[1] > screenHeight + 500:
        running = False

    #displayFPS(screen, 20)
    pygame.display.flip()
    clock.tick(60)

pygame.quit()